steps.script:
$ErrorActionPreference='Stop'
$sourceSha='51b6f70504cad0594a85f290e84d791edb38f09b'
$o=@{mode='guard_only';commit=$sourceSha;result='not_started';backup_verified=$false;guard_updated=$false;source_verified=$false;active_runner_count=0;exit_code=$null;chrome_touched=$false}
try {
 $url='https://raw.githubusercontent.com/fabricelop/europapress-rss/'+$sourceSha+'/windows/Reparar-TT-Editorial-20261111.ps1'
 $scriptPath=Join-Path $env:TEMP ('tt-editorial-guard-only-'+$sourceSha.Substring(0,12)+'.ps1')
 Invoke-WebRequest -UseBasicParsing -Uri $url -OutFile $scriptPath -TimeoutSec 30 -ErrorAction Stop
 $source=Get-Content -LiteralPath $scriptPath -Raw -Encoding UTF8 -ErrorAction Stop
 if(-not($source.Contains('function confirmedUserState(s,marker)') -and $source.Contains('TRANSMISSION_STATE') -and $source.Contains('GUARD_ONLY_INSTALLED') -and $source.Contains("if(entry?.status==='submit_intent')"))){throw 'SOURCE_VALIDATION_FAILED'}
 $o.source_verified=$true
 $nodes=@(Get-CimInstance Win32_Process -Filter "Name='node.exe'" -ErrorAction Stop | Where-Object { [string]$_.CommandLine -match '(?i)(?:[\\/]|\b)(?:Ejecutar[.]js|Ejecutar[.]TT-Original[.]js|TT-Editorial-Guard[.]js)(?:\s|"|$)' })
 $o.active_runner_count=$nodes.Count
 if($nodes.Count -gt 0){$o.result='deferred_busy';Write-Output ('TTRESULT:'+($o|ConvertTo-Json -Compress));exit 0}
 $outFile=Join-Path $env:TEMP ('tt-guard-only-'+$sourceSha.Substring(0,12)+'.stdout.log')
 $errFile=Join-Path $env:TEMP ('tt-guard-only-'+$sourceSha.Substring(0,12)+'.stderr.log')
 $p=Start-Process -FilePath "$env:WINDIR\System32\WindowsPowerShell\v1.0\powershell.exe" -ArgumentList @('-NoProfile','-NonInteractive','-ExecutionPolicy','Bypass','-File',('"'+$scriptPath+'"'),'-GuardOnly','-NoDispatch') -Wait -PassThru -RedirectStandardOutput $outFile -RedirectStandardError $errFile -ErrorAction Stop
 $o.exit_code=$p.ExitCode
 $g='C:\TTiTTulares\TT-Editorial-Guard.js'
 if($p.ExitCode -eq 0 -and (Test-Path -LiteralPath $g)){
  $txt=Get-Content -LiteralPath $g -Raw -Encoding UTF8 -ErrorAction Stop
  $o.guard_updated=$txt.Contains('function confirmedUserState(s,marker)') -and $txt.Contains('TRANSMISSION_STATE')
  $o.backup_verified=Test-Path -LiteralPath 'C:\TTiTTulares\TT-Editorial-Rescue\installed.json'
 }
 $o.result=if($o.guard_updated -and $o.backup_verified){'installed_verified'}else{'install_not_verified'}
}catch{$o.result='error';$o.error_class=$_.Exception.GetType().Name}
Write-Output ('TTRESULT:'+($o|ConvertTo-Json -Compress))
